package com.microbms.gateway;
import io.jsonwebtoken.Claims; import io.jsonwebtoken.Jwts; import io.jsonwebtoken.security.Keys;
import org.springframework.cloud.gateway.filter.GatewayFilterChain; import org.springframework.cloud.gateway.filter.GlobalFilter; import org.springframework.core.Ordered; import org.springframework.http.HttpHeaders; import org.springframework.http.HttpStatus; import org.springframework.http.server.reactive.ServerHttpRequest; import org.springframework.stereotype.Component; import org.springframework.web.server.ServerWebExchange; import reactor.core.publisher.Mono;
import java.nio.charset.StandardCharsets; import java.util.Base64;
@Component public class TokenFilter implements GlobalFilter, Ordered {
 private final javax.crypto.SecretKey key;
 public TokenFilter(LocalJwtSecret secretProvider){String secret=secretProvider.get();byte[] bytes;try{bytes=Base64.getDecoder().decode(secret);}catch(IllegalArgumentException e){bytes=secret.getBytes(StandardCharsets.UTF_8);}key=Keys.hmacShaKeyFor(bytes);}
 @Override public int getOrder(){return -1;}
 @Override public Mono<Void> filter(ServerWebExchange exchange,GatewayFilterChain chain){String path=exchange.getRequest().getURI().getPath();if(path.equals("/api/auth/register")||path.equals("/api/auth/login"))return chain.filter(exchange);String auth=exchange.getRequest().getHeaders().getFirst(HttpHeaders.AUTHORIZATION);if(auth==null||!auth.startsWith("Bearer "))return reject(exchange,"A valid Bearer token is required");try{Claims claims=Jwts.parser().verifyWith(key).build().parseSignedClaims(auth.substring(7)).getPayload();String userId=claims.getSubject();if(userId==null) return reject(exchange,"Invalid token");ServerHttpRequest request=exchange.getRequest().mutate().headers(h->{h.remove("X-User-Id");h.set("X-User-Id",userId);}).build();return chain.filter(exchange.mutate().request(request).build());}catch(Exception e){return reject(exchange,"Invalid or expired token");}}
 private Mono<Void> reject(ServerWebExchange e,String message){e.getResponse().setStatusCode(HttpStatus.UNAUTHORIZED);e.getResponse().getHeaders().setContentType(org.springframework.http.MediaType.APPLICATION_JSON);byte[] body=("{\"error\":\"unauthorized\",\"message\":\""+message+"\"}").getBytes(StandardCharsets.UTF_8);return e.getResponse().writeWith(Mono.just(e.getResponse().bufferFactory().wrap(body)));}
}
